import {
  CASES, CaseNo, Gender, GrammarReading, NumberNo, PARADIGMS, Paradigm, Person, VerbAnalysis, VerbEnding,
} from './sanskritGrammar';
import { slp1ToIast } from './sanskritTranslit';
import { ROOT_MEANINGS } from '@/constants/sanskritRoots';

/**
 * Readings of a word form from the form lexicon (assets/dictionary/forms.dict,
 * built with Vidyut by scripts/build-forms.py): the genuine grammatical
 * readings of every word in Śrīla Prabhupāda's word-for-word, generated by a
 * Pāṇinian grammar rather than guessed from endings. The analysis only has
 * to choose among them.
 *
 * Record formats (see the build script):
 *   N|stem|gender|case|number|lexical genders|krt|root|prefixes
 *   A|stem
 *   V|root|prefixes|gana|lakara|person|number|prayoga|sanadi|table-key|morphemes|sutras
 */

export type LexReading =
  | { kind: 'noun'; stem: string; gender: Gender | null; case: CaseNo; number: NumberNo; lexGenders: Gender[];
    krt: string | null; root: string | null; prefixes: string[] }
  | { kind: 'avyaya'; stem: string }
  | { kind: 'verb'; root: string; prefixes: string[]; gana: string; lakara: string; person: Person; number: NumberNo;
    prayoga: string; sanadi: string[]; tableKey: string; morphemes: string[]; sutras: string[];
    /** P parasmaipada / A ātmanepada, from the ending the derivation used. */
    pada: string };

export function parseLexReadings(raw: string): LexReading[] {
  return raw.split('\x1f').map((r): LexReading | null => {
    const f = r.split('|');
    if (f[0] === 'A') return { kind: 'avyaya', stem: f[1] };
    if (f[0] === 'N') {
      return {
        kind: 'noun', stem: f[1], gender: (f[2] || null) as Gender | null, case: Number(f[3]) as CaseNo,
        number: Number(f[4]) as NumberNo, lexGenders: [...(f[5] ?? '')] as Gender[], krt: f[6] || null,
        root: f[7] || null, prefixes: f[8] ? f[8].split('-') : [],
      };
    }
    if (f[0] === 'V') {
      return {
        kind: 'verb', root: f[1], prefixes: f[2] ? f[2].split('-') : [], gana: f[3], lakara: f[4],
        person: Number(f[5]) as Person, number: Number(f[6]) as NumberNo, prayoga: f[7],
        sanadi: f[8] ? f[8].split('-') : [], tableKey: f[9], morphemes: f[10] ? f[10].split('+') : [],
        sutras: f[11] ? f[11].split(',') : [],
        pada: f[12] ?? '',
      };
    }
    return null;
  }).filter((r): r is LexReading => !!r);
}

