// ── Readings ────────────────────────────────────────────────────────────

/** Declension pattern of a stem, for "like rāma → rāmaḥ". */
export function paradigmFor(stem: string, gender: Gender | null): Paradigm | null {
  const g = gender ?? 'm';
  // Diphthong stems (go, nau, rai) are irregular: no table to compare with.
  if (/[oOE]$/.test(stem)) return null;
  const id =
    /an$/.test(stem) ? (g === 'n' ? 'an-n' : 'an-m')
      : /in$/.test(stem) ? 'in-m'
        : /(v|m)at$/.test(stem) ? 'at-m'
          : /at$/.test(stem) ? 'ant-m'
            : /as$/.test(stem) && g === 'n' ? 'as-n'
              : /a$/.test(stem) ? (g === 'n' ? 'a-n' : g === 'f' ? 'A-f' : 'a-m')
                : /A$/.test(stem) ? 'A-f'
                  : /i$/.test(stem) ? (g === 'f' ? 'i-f' : g === 'n' ? 'i-n' : 'i-m')
                    : /I$/.test(stem) ? 'I-f'
                      : /u$/.test(stem) ? 'u-m'
                        : /f$/.test(stem) ? 'f-m'
                          : 'cons';
  return PARADIGMS.find(p => p.id === id) ?? null;
}


/** The tense label of a verb reading: "present (laṭ)", "future, passive (lṛṭ)" … */
export function tenseLabel(r: Extract<LexReading, { kind: 'verb' }>): string {
  const base = LAKARA_LABEL[r.lakara] ?? r.lakara;
  const extra = [
    r.prayoga === 'Karmani' ? 'passive' : r.prayoga === 'Bhave' ? 'impersonal' : r.pada === 'A' ? 'ātmanepada' : '',
    r.sanadi.includes('Ric') ? 'causative' : r.sanadi.includes('san') ? 'desiderative' : r.sanadi.includes('yaN') ? 'intensive' : '',
  ].filter(Boolean);
  return extra.length ? base.replace(/ \(/, `, ${extra.join(', ')} (`) : base;
}

/**
 * The lexicon's readings of a form as GrammarReadings, scored like the
 * analysis's own: Prabhupāda's English picks the case / the verb, and rare
 * readings (vocative, dual, passive, derived, future participle) wait unless
 * his English points to them.
 */
export function lexiconReadings(
  lex: LexReading[], hint: string | null | undefined, hintedCases: CaseNo[], verbal: boolean,
  opts: { compoundFinal?: boolean } = {},
): GrammarReading[] {
  const out: GrammarReading[] = [];
  const h = (hint ?? '').trim().toLowerCase();
  // When the form is also a plain noun (ācāryāḥ, avyayam, māyām), a verb
  // reading must earn its place: his English has to read as a verb.
  const hasNoun = lex.some(r => r.kind === 'noun' && !r.krt);
  const hintPronoun = /^(i|we|you|me|us)\b/.test(h);
  const hasVac = lex.some(r => r.kind === 'verb' && r.root === 'vac');
  const hasVacAny = lex.some(r => r.kind !== 'avyaya' && r.root === 'vac');
  const hintPassive = /^(is|are|was|were|be|being|been)\b.*\b\w+(ed|en)\b/.test(h) || /\bby\b/.test(h);
  // Of two roots that give the same form (vakṣyāmi: √vac "speak" / √vah
  // "carry"), the one whose sense his English shares.
  const hintWords = h.split(/[^a-z]+/).filter(w => w.length > 2 && !['the', 'and', 'for', 'one', 'who', 'has', 'are', 'was', 'shall', 'will'].includes(w));
  const rootFits = (root: string | null | undefined) => {
    const gloss = root ? ROOT_MEANINGS[root] : undefined;
    if (!gloss || !hintWords.length) return false;
    const gw = gloss.toLowerCase().split(/[^a-z]+/).filter(w => w.length > 2 && w !== 'with');
    return hintWords.some(w => gw.some(g => w.startsWith(g.slice(0, Math.max(4, g.length - 2))) || g.startsWith(w)));
  };
  const someRootFits = lex.some(r => (r.kind === 'verb' || (r.kind === 'noun' && r.krt)) && rootFits(r.root));
  for (const r of lex) {
    if (r.kind === 'avyaya') continue;
    if (r.kind === 'verb') {
      // The last word of a hyphenated compound is never a finite verb.
      if (opts.compoundFinal) continue;
      // His English clearly names a thing ("the teachers", "imperishable"):
      // no verb alternative for a form that is also a noun.
      if (hasNoun && nominalHint(h)) continue;
      const v: VerbEnding = { ending: '', tense: tenseLabel(r), person: r.person, number: r.number };
      let score = verbal ? 0.4 : hintedCases.length ? 1.6 : 0.9;
      if (hasNoun && !verbal) score += 0.8;
      if (r.person !== 3 && !hintPronoun) score += 0.4;
      if ((r.lakara === 'Lan' || r.lakara === 'Lun' || r.lakara === 'AshirLin') && hasNoun) score += 0.4;
      // √vac, not its brū stand-in (2.4.53), is the root readers look for.
      if (r.root === 'brU' && hasVac) score += 0.3;
      if (r.prayoga === 'Karmani' && !hintPassive) score += 0.6;
      if (r.sanadi.length) score += 0.3;
      if (someRootFits && !rootFits(r.root)) score += 0.4;
      if (r.prayoga === 'Karmani' && hintPassive) score -= 0.3;
      // "practicing", "seeing": his -ing is a participle, when the form is one too.
      if (/^\w+ing$/.test(h) && lex.some(x => x.kind === 'noun' && (x.krt === 'Satf' || x.krt === 'SAnac'))) continue;
      if (r.number === 1) score += 0.2;
      if (r.lakara === 'Let' || r.lakara === 'Lrn') score += 0.5;
      out.push({ kind: 'verb', stem: r.root, prefix: r.prefixes.join('-') || undefined, verb: v, score, lex: r });
      continue;
    }
    const krt = r.krt ? KRT_LABEL[r.krt] : null;
    if (krt && (krt.kind === 'gerund' || krt.kind === 'infinitive')) {
      const label = r.krt === 'ktvA' && r.prefixes.length ? KRT_LABEL.lyap.label : krt.label;
      out.push({
        kind: 'verb', stem: r.root ?? r.stem, prefix: r.prefixes.join('-') || undefined,
        verb: { ending: '', tense: '', form: label }, lex: r,
        score: (verbal ? 0.5 : 1.0) + (r.root === 'brU' && hasVacAny ? 0.5 : 0) + (someRootFits && !rootFits(r.root) ? 0.4 : 0),
      });
      continue;
    }
    let score = (krt ? 1.2 : 1.0) + caseMisfit(r.case, h);
    // A bare verb in his English ("worship", "know it") for a form that is also a verb.
    if (h && !hintedCases.length && lex.some(x => x.kind === 'verb') && !nominalHint(h)) score += 0.6;
    if (hintedCases.length) score += hintedCases.includes(r.case) ? -0.5 : 0.4;
    if (r.case === 8) score += /^o\s/.test(h) ? -0.3 : 0.5;
    // The word's own noun (karman, loc. karmaṇi) before an adjective of
    // another stem that happens to share the form (karmin, neut. karmaṇi).
    if (r.lexGenders.length === 3 && lex.some(x => x.kind === 'noun' && !x.krt && x.stem !== r.stem && x.lexGenders.length > 0 && x.lexGenders.length < 3)) score += 0.3;
    // The dual is rare: below a locative that his English doesn't mark.
    if (r.number === 1) score += 0.6;
    if (verbal && !krt) score += 0.3;
    // His English as a past participle ("settled", "given", "gone"): the
    // kta reading over a plain noun of the same stem (datta "gift").
    // "practicing", "acting upon": a present participle.
    if ((r.krt === 'Satf' || r.krt === 'SAnac') && /^\w+ing\b/.test(h)) score -= 0.4;
    if (krt?.kind === 'participle' && r.krt === 'kta' && PAST_ENGLISH.test(h.replace(/^(being|been|having been|is|are|was|were|has been|have been|all)\s+/, '').split(/[\s,;]/)[0])) score -= 0.3;
    // ā-hita from ā + √dhā, not a bare root that happens to fit (√ah).
    // Of homonymous roots, the common one (√dhā over √hi for hita).
    if (krt && !ROOT_MEANINGS[r.root ?? ''] && lex.some(x => x.kind === 'noun' && x.krt && x.stem === r.stem && ROOT_MEANINGS[x.root ?? ''])) score += 0.05;
    if (krt && !r.prefixes.length && lex.some(x => x.kind === 'noun' && x.krt && x.stem === r.stem && x.prefixes.length)) score += 0.15;
    // Roots in -e / -ai / -o (de, gai): their homonym in -ā (dā) is the usual one.
    if (krt && /[eEoO]$/.test(r.root ?? '')) score += 0.1;
    if (krt && someRootFits && !rootFits(r.root)) score += 0.4;
    // √vac, not its brū stand-in, for a derived form too (prativaktum).
    if (krt && r.root === 'brU' && hasVacAny) score += 0.5;
    // "O Arjuna", "O son of Kuntī": a person addressed by name — a noun,
    // and not neuter (arjuna is also the adjective "white").
    // A person addressed ("O descendant of Bharata", "O Arjuna") is not neuter.
    const addressed = r.case === 8 && /^O\s/.test((hint ?? '').trim());
    const addressedByName = addressed && /\b[A-ZĀĪŪṚṢŚÑṆ][a-zāīūṛṣśñṇṭḍḥṁ]+/.test((hint ?? '').trim().slice(2));
    if (addressed && r.gender === 'n' && lex.some(x => x.kind === 'noun' && x.case === 8 && x.gender !== 'n')) continue;
    // A participle / gerundive, or a stem the lexicon gives all three genders.
    const adjective = !addressedByName && (!!krt || r.lexGenders.length === 3 || r.lexGenders.length === 0);
    out.push({
      kind: 'noun', stem: r.stem, paradigm: paradigmFor(r.stem, r.gender) ?? undefined,
      gender: r.gender ? [r.gender] : [], case: r.case, number: r.number, score,
      adjective, participleOf: krt?.kind === 'participle' ? r.root ?? undefined : undefined, lex: r,
    });
  }
  return out.sort((a, b) => a.score - b.score);
}

/** His English names a thing or a quality, not an action. */
export function nominalHint(h: string): boolean {
  return /^(the|a|an|all|his|her|their|my|your|our|this|that|these|those|of|in|on|at|by|with|from|for|to the|unto|o|one who|those who|he who)\b/.test(h)
    || /^\w{3,}(ness|tion|sion|ment|ity|ers|ors|ance|ence|able|ible|ful|less|ous|ive|hood|ism|ist)\b/.test(h);
}

/**
 * How badly a case fits his English (0 = fine). He renders an oblique case
 * with its preposition — "in …", "by …", "to …", "from …", "of …" — so a
 * locative read where his English has no "in / on / when" is unlikely.
 */
export function caseMisfit(c: number, h: string): number {
  if (!h) return 0;
  const first = h.split(/\s+/)[0];
  switch (c) {
    case 3: return /^(by|with|through|because|due|on account|in)\b/.test(h) || /\b(by|with)\b/.test(h) ? 0 : 0.4;
    case 4: return /^(to|for|unto|towards)\b/.test(h) || /\bfor\b/.test(h) ? 0 : 0.4;
    case 5: return /^(from|than|because|due|out of)\b/.test(h) || /\bfrom\b/.test(h) ? 0 : 0.4;
    case 6: return /^(of|whose|my|your|his|her|their|our|its)\b/.test(h) || /'s$|s'$/.test(first) || /\bof\b/.test(h) ? 0 : 0.3;
    case 7: return /^(in|on|at|within|upon|among|when|while|during|into|for|unto|to|with|about|regarding)\b/.test(h) || /\b(in|on|when|while)\b/.test(h) ? 0 : 0.3;
    default: return 0;
  }
}

const PAST_ENGLISH = /\b(\w{3,}ed|given|gone|done|born|seen|known|made|got|lost|spoken|fallen|bound|taken|begotten|driven|forgotten|hidden|risen|thrown|torn|worn|won|written|brought|thought|caught|taught|bought|sent|spent|left|kept|held|heard|said|told|come|become)\b/;

/** A krt label for a reading ("past participle (kta) of √gam"), or null. */
export function krtLabel(r: LexReading | undefined): string | null {
  if (!r || r.kind !== 'noun' || !r.krt) return null;
  // With a prefix, ktvā is replaced by lyap (samāse 'nañpūrve ktvo lyap, 7.1.37).
  const k = r.krt === 'ktvA' && r.prefixes.length ? KRT_LABEL.lyap : KRT_LABEL[r.krt];
  if (!k) return null;
  // vidvas: √vid's śatṛ is replaced by vasu (vider śatur vasuḥ, 7.1.36).
  if (r.krt === 'Satf' && /vas$/.test(r.stem)) return `present participle (śatṛ → vasu, 7.1.36) of √${slp1ToIast(r.root ?? '')}`;
  const pre = r.prefixes.length ? `${r.prefixes.map(slp1ToIast).join('- + ')}- + ` : '';
  return `${k.label} of ${pre}√${slp1ToIast(r.root ?? '')}`;
}

/**
 * A verb broken down from Vidyut's own derivation: its morphemes (pra + vad
 * + a + anti) labelled upasarga / dhātu / vikaraṇa / ending, its full table,
 * and the sūtras that shaped it.
 */
export function verbAnalysisFromLexicon(
  r: Extract<LexReading, { kind: 'verb' }>, table: string[] | null,
): VerbAnalysis {
  const pieces = [...r.morphemes];
  const prefixes = pieces.splice(0, Math.min(r.prefixes.length, pieces.length)).map(slp1ToIast);
  const stem = pieces.shift() ?? r.root;
  const tin = pieces.pop() ?? '';
  const middle = pieces.join(' + ');
  const vik = GANA_VIKARANA[r.gana];
  const markerLabel = r.lakara === 'Lrt' ? 'future marker -sya-'
    : r.lakara === 'AshirLin' || r.lakara === 'VidhiLin' ? 'optative / benedictive marker'
      : r.prayoga === 'Karmani' ? 'passive marker -ya- (yak)'
        : r.sanadi.includes('Ric') ? 'causative -aya- (ṇic)'
          : vik ? vik.label : 'vikaraṇa';
  const notes = r.sutras.filter(s => SUTRA_NOTES[s]).map(s => `Pāṇini ${s}: ${SUTRA_NOTES[s]}`);
  const rows = table ? [table.slice(0, 3), table.slice(3, 6), table.slice(6, 9)].map(row => row.map(c => (c === '—' ? '—' : slp1ToIast(c)))) : null;
  return {
    prefixes,
    root: slp1ToIast(r.root),
    stem: slp1ToIast(stem + middle),
    marker: middle ? { text: slp1ToIast(middle), label: markerLabel } : null,
    tin: slp1ToIast(tin),
    bookEnding: null,
    tense: tenseLabel(r),
    person: r.person,
    number: r.number,
    table: rows,
    notes,
    substitute: stem !== r.root ? { text: slp1ToIast(stem), label: `√${slp1ToIast(r.root)} as it stands in this form` } : null,
  };
}

export const caseName = (c: CaseNo) => CASES[c - 1].english;
